(5076244, 740268, 59029, '<td valign="top">that bird may have some ''egrets'' if he gets too close to Art, lol!  He could well be skulking in there enroute to a village burning...:-)</td>', 'that bird may have some ''egrets'' if he gets too close to Art, lol!  He could well be skulking in there enroute to a village burning...:-)', '2008-11-20 16:35:40.000000', NULL, 1),
(5076251, 740310, 59029, '<td valign="top">bwwwahahhahahahaahaa! Unleash the ducks of war! Great concept, great comp, love the torch and fistful of matches and the looks on duckies faces are terrific.  Details like those are why I give shots like this a 9.</td>', 'bwwwahahhahahahaahaa! Unleash the ducks of war! Great concept, great comp, love the torch and fistful of matches and the looks on duckies faces are terrific.  Details like those are why I give shots like this a 9.', '2008-11-20 16:37:28.000000', NULL, 1),
(5076253, 740171, 59029, '<td valign="top">very serene shot...almost too serene if Art''s meant to be around :-) nice comp, good colours and lighting.</td>', 'very serene shot...almost too serene if Art''s meant to be around :-) nice comp, good colours and lighting.', '2008-11-20 16:38:23.000000', NULL, 1),
(5076255, 740247, 59029, '<td valign="top">very cool building, love the light here, dof great, nice and atmospheric. 8</td>', 'very cool building, love the light here, dof great, nice and atmospheric. 8', '2008-11-20 16:40:10.000000', NULL, 1),
(5076256, 740337, 59029, '<td valign="top">...tying woody hostages to signs, eh? what a heartless SOB! ;-) love the hitchhiker being (wisely)passed by. 7</td>', '...tying woody hostages to signs, eh? what a heartless SOB! ;-) love the hitchhiker being (wisely)passed by. 7', '2008-11-20 16:41:40.000000', NULL, 1),
